	@Test
	void query2DeadlineBeforeAnyPricedPlanStillReturnsAPricedPlanThatFinishes(@TempDir File dataDir)
			throws Exception {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "budgeted");
		String previousBudget = System.setProperty(LmdbCascadesOptimizer.BUDGET_PROPERTY, "256");
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				new AASGenerator().generateAndAdd(connection, 100, 100, 100);
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			// The test clock puts the wall-clock deadline after 16 search work units. A search stopped there has no
			// priced root plan yet and would return the written-order plan (a Cartesian pair first, root price
			// unavailable), which does not finish within minutes; the search must instead run on to its first priced
			// root plan.
			try (SailRepositoryConnection connection = repository.getConnection();
					LmdbBenchmarkQueryPlan plan = PackedPlanningDeadlineTestSupport.withDeadlineAfterSearchWork(16L,
							() -> LmdbBenchmarkQueryPlan.prepare(store, connection, QUERY, 30, true))) {
				TupleExpr[] optimized = new TupleExpr[1];
				plan.inspectCapturedOptimizedExpression(root -> optimized[0] = root);
				TupleExpr root = optimized[0];
				String described = plan.optimizedPlan();
				assertEquals("AVAILABLE", root.getStringMetricPlanned("optimizer.cascadesPriceAvailability"),
						() -> "The deadline must not return a plan without a price:\n" + described);
				assertEquals("first-priced-plan", root.getStringMetricPlanned("optimizer.cascadesDeadlineOverrunStop"),
						() -> "The search must run past the deadline to its first priced root plan:\n" + described);
				assertTrue(root.getDoubleMetricPlanned("optimizer.cascadesDeadlineOverrunNanos") > 0.0d);
				assertEquals("DEADLINE_EXPIRED", root.getStringMetricPlanned("optimizer.cascadesCompleteness"));
				TupleExpr selected = root instanceof QueryRoot queryRoot ? queryRoot.getArg() : root;
				assertEquals(0.0d, selected.getDoubleMetricPlanned("plannedCostCartesianWorkRows"),
						() -> "The priced plan must not introduce Cartesian work:\n" + described);

				long count = -1L;
				try (var result = plan.evaluate()) {
					while (result.hasNext()) {
						count = ((Literal) result.next().getValue("c")).longValue();
					}
				}
				assertEquals(6679L, count, "The priced plan must finish within the query's 30 s limit");
			}
		} finally {
			repository.shutDown();
			restoreProperty(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
			restoreProperty(LmdbCascadesOptimizer.BUDGET_PROPERTY, previousBudget);
		}
	}

